package com.witchersbestiary.client.signs;
import com.witchersbestiary.signs.*;import net.minecraft.client.*;import net.minecraft.client.option.KeyBinding;import net.minecraft.client.util.InputUtil;import net.minecraft.client.gui.*;import net.minecraft.client.gui.screen.Screen;import net.minecraft.text.Text;import net.fabricmc.fabric.api.client.keybinding.v1.KeyBindingHelper;import net.fabricmc.fabric.api.client.event.lifecycle.v1.ClientTickEvents;import net.fabricmc.fabric.api.client.rendering.v1.HudRenderCallback;import net.fabricmc.fabric.api.client.networking.v1.*;import org.lwjgl.glfw.GLFW;import java.util.*;
public final class SignsClient {
 public static SignPackets.View view;private static long sequence;private static KeyBinding menu,cast,settings;
 public static void send(int action,int sign){if(view!=null)ClientPlayNetworking.send(new SignPackets.Intent(view.session(),++sequence,action,sign));}
 private static boolean held(MinecraftClient c,KeyBinding binding){var key=KeyBindingHelper.getBoundKeyOf(binding);return key.getCategory()==InputUtil.Type.MOUSE?GLFW.glfwGetMouseButton(c.getWindow().getHandle(),key.getCode())==GLFW.GLFW_PRESS:key.getCode()>=0&&InputUtil.isKeyPressed(c.getWindow().getHandle(),key.getCode());}
 public static void symbol(DrawContext c,SignType s,int x,int y,int size){int color=s.color;boolean down=s==SignType.QUEN||s==SignType.AXII;for(int i=0;i<size;i++){int yy=y+(down?size-i:i);int half=i/2;c.fill(x-half,yy,x-half+2,yy+2,color);c.fill(x+half,yy,x+half+2,yy+2,color);}c.fill(x-size/2,y+(down?0:size),x+size/2+2,y+(down?0:size)+2,color);if(s==SignType.AARD||s==SignType.AXII)c.fill(x-size/3,y+size/2,x+size/3+1,y+size/2+2,color);if(s==SignType.YRDEN){for(int i=0;i<size;i++){c.fill(x-size/2+i,y+i,x-size/2+i+2,y+i+2,color);c.fill(x+size/2-i,y+i,x+size/2-i+2,y+i+2,color);}c.fill(x-size/2,y,x+size/2+1,y+2,color);}}
 public static String name(SignType s){return Text.translatable("sign.witchersbestiary."+s.name().toLowerCase(Locale.ROOT)).getString();}
 public static void initialize(){menu=KeyBindingHelper.registerKeyBinding(new KeyBinding("key.witchersbestiary.sign_menu",InputUtil.Type.KEYSYM,GLFW.GLFW_KEY_R,"key.categories.gameplay"));cast=KeyBindingHelper.registerKeyBinding(new KeyBinding("key.witchersbestiary.sign_cast",InputUtil.Type.KEYSYM,GLFW.GLFW_KEY_G,"key.categories.gameplay"));settings=KeyBindingHelper.registerKeyBinding(new KeyBinding("key.witchersbestiary.sign_hud",InputUtil.Type.KEYSYM,GLFW.GLFW_KEY_UNKNOWN,"key.categories.gameplay"));ClientPlayNetworking.registerGlobalReceiver(SignPackets.View.ID,(p,c)->c.client().execute(()->view=p));ClientPlayConnectionEvents.DISCONNECT.register((h,c)->{view=null;sequence=0;});ClientTickEvents.END_CLIENT_TICK.register(c->{if(c.player==null||!c.isWindowFocused()){if(c.currentScreen instanceof Radial)c.setScreen(null);return;}if(c.currentScreen==null){while(settings.wasPressed())c.setScreen(new SignHudScreen());if(menu.isPressed()&&view!=null)c.setScreen(new Radial());while(cast.wasPressed())if(view!=null)send(1,view.selected());}else{while(cast.wasPressed()){}if(c.currentScreen instanceof Radial r&&!held(c,menu))r.confirm();}});HudRenderCallback.EVENT.register((c,t)->{var mc=MinecraftClient.getInstance();if(view!=null&&view.learned()!=0&&mc.player!=null&&!mc.options.hudHidden)drawHud(c,mc);});}
 public static void drawHud(DrawContext c,MinecraftClient mc){var b=SignHudSettings.bounds(mc.getWindow().getScaledWidth(),mc.getWindow().getScaledHeight());c.getMatrices().push();c.getMatrices().translate(b[0],b[1],0);c.getMatrices().scale(b[4]/10000f,b[4]/10000f,1);var s=SignType.byIndex(view==null?0:view.selected());float energy=view==null?70:view.energy();c.fill(0,0,180,48,0xdc181b1e);c.fill(0,0,180,1,0xffb29560);symbol(c,s,15,5,13);c.drawTextWithShadow(mc.textRenderer,name(s),28,6,s.color);c.drawTextWithShadow(mc.textRenderer,String.format(Locale.ROOT,"%.0f / 100",energy),105,6,0xffe0dfd7);c.fill(8,21,172,28,0xff363e41);c.fill(8,21,8+(int)(164*energy/100),28,0xff69bdcf);String status=view==null?"":String.format(Locale.ROOT,"%.1fs   Quen %.1f   Yrden %.1fs",view.cooldown()/20f,view.shield(),view.trapTicks()/20f);c.drawTextWithShadow(mc.textRenderer,status,8,34,0xffd2c7b1);c.getMatrices().pop();}
 private static final class Radial extends Screen {private SignType hover;Radial(){super(Text.literal("Witcher signs"));}public boolean shouldPause(){return false;}public void confirm(){if(hover!=null&&(view.learned()&(1<<hover.ordinal()))!=0)send(0,hover.ordinal());close();}public void render(DrawContext c,int mx,int my,float delta){double radius=Math.min(110,Math.min(width,height)*.36),dx=mx-width/2.,dy=my-height/2.;double angle=(Math.atan2(dy,dx)+Math.PI/2+Math.PI/5+Math.PI*2)%(Math.PI*2);hover=dx*dx+dy*dy>28*28?SignType.values()[(int)(angle/(Math.PI*2/5))]:null;for(int y=(int)-radius;y<=radius;y++){int run=-(int)radius,previous=0;for(int x=-(int)radius;x<=(int)radius+1;x++){double rr=x*x+y*y,aa=(Math.atan2(y,x)+Math.PI/2+Math.PI/5+Math.PI*2)%(Math.PI*2);int current=rr>32*32&&rr<radius*radius?(hover==SignType.values()[(int)(aa/(Math.PI*2/5))]?0xd04e4431:0xd0191d21):0;if(current!=previous){if(previous!=0)c.fill(width/2+run,height/2+y,width/2+x,height/2+y+1,previous);run=x;previous=current;}}}for(var s:SignType.values()){double center=-Math.PI/2+s.ordinal()*Math.PI*2/5;boolean known=(view.learned()&(1<<s.ordinal()))!=0;int x=width/2+(int)(Math.cos(center)*radius*.68),y=height/2+(int)(Math.sin(center)*radius*.68);symbol(c,s,x,y-20,12);c.drawCenteredTextWithShadow(textRenderer,name(s),x,y,known?s.color:0xff777777);c.drawCenteredTextWithShadow(textRenderer,known?""+s.cost:"[X]",x,y+13,0xffc8bfa9);}c.drawCenteredTextWithShadow(textRenderer,"WB",width/2,height/2-4,0xffbba475);if(hover!=null)c.drawCenteredTextWithShadow(textRenderer,name(hover)+"  "+hover.cost+" / "+hover.cooldown/20+"s",width/2,(int)(height/2+radius+12),view.energy()<hover.cost?0xffff8866:hover.color);}}
}
